/**
 * @name Command injection
 * @description Command injection via os.system, subprocess, or similar
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // System command execution via os.system, subprocess, etc.
    exists(DataFlow::CallCfgNode call |
      // os.system(command)
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // subprocess.call(command, ...)
      call = API::moduleImport("subprocess").getMember(["call", "Popen", "run", "check_call", "check_output"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // os.popen(command)
      call = API::moduleImport("os").getMember("popen").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal
 * @description Path traversal via file operations with user-controlled input
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File system operations that accept paths
    exists(DataFlow::CallCfgNode call |
      // open() built-in
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // os.path operations
      call = API::moduleImport("os").getMember("path").getMember(["join", "abspath", "realpath", "normpath"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // os module file operations
      call = API::moduleImport("os").getMember(["open", "remove", "unlink", "rename", "chdir", "mkdir", "makedirs", "rmdir", "listdir", "stat", "lstat", "chmod", "chown", "utime", "walk"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // built-in file operations
      call = API::builtin(["file", "execfile"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name SQL injection
 * @description SQL injection via database APIs
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
