module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // SQL execution via various database APIs
    exists(DataFlow::CallCfgNode call |
      // sqlite3
      call = API::moduleImport("sqlite3").getMember(["execute", "executemany", "executescript"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // MySQL/mysql.connector
      call = API::moduleImport("mysql.connector").getMember(["execute", "executemany"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // psycopg2
      call = API::moduleImport("psycopg2").getMember(["execute", "executemany"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // pyodbc
      call = API::moduleImport("pyodbc").getMember(["execute", "executemany"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
